-- =====================================================================
--  Migration 006 · Tipps & Tricks (Texte aus dem Prototyp)
-- =====================================================================
--  14 Tipps, alle auf Deutsch und sofort veröffentlicht.
--  Neue oder geänderte Tipps: neue Migration, diese Datei nicht ändern.
-- =====================================================================

create temp table _tips as
select * from jsonb_to_recordset($json$[
{"slug": "kurvenfahren", "category": "cornering", "difficulty": 2, "sort": 1, "title": "Kurvenfahren", "summary": "Wer vor der Kurve das richtige Tempo wählt, fährt sie ruhig und sicher.", "body": "Wer vor der Kurve das richtige Tempo wählt, fährt sie ruhig und sicher.\n\n1. Vor der Kurve die Geschwindigkeit anpassen und den passenden Gang wählen. In der Kurve kannst du nicht mehr stark bremsen oder stark Gas geben.\n2. Den Blick früh zum Kurvenausgang richten und den Kopf mitdrehen.\n3. Ab etwa 50 km/h lenkst du mit Gegenlenken ein: den Lenker leicht in Kurvenrichtung drücken, also rechts drücken, um nach rechts zu fahren. Beim langsamen Fahren nicht gegenlenken, dort lenkst du ganz normal.\n4. Ab der Kurvenmitte sanft Gas geben und das Motorrad dabei langsam aufrichten.\n5. Achte schon vor der Kurve auf Schachtdeckel, Laub, Fahrbahnmarkierungen, Schienen und Dreck und weiche ihnen möglichst aus, auch bei trockener Strasse. In Schräglage haben die Reifen darauf besonders wenig Halt.\n\n> **Übung:** Übe das Gegenlenken erst ab etwa 50 km/h, zum Beispiel auf einer ruhigen Landstrasse oder in einem Fahrsicherheitstraining. Spüre bewusst, wie ein leichter Druck am Lenker das Motorrad in die Schräglage bringt."},
{"slug": "blickfuehrung", "category": "basics", "difficulty": 1, "sort": 2, "title": "Blickführung", "summary": "Das Motorrad fährt dorthin, wo du hinschaust. Mit dem richtigen Blick fährst du Kurven ruhiger und reagierst früher.", "body": "Das Motorrad fährt dorthin, wo du hinschaust. Mit dem richtigen Blick fährst du Kurven ruhiger und reagierst früher.\n\n1. Weit vorausschauen, nicht direkt vor das Vorderrad.\n2. In der Kurve den Kopf drehen und zum Kurvenausgang schauen, nicht nur die Augen bewegen.\n3. Nicht auf Hindernisse starren. Wer auf ein Schlagloch schaut, fährt oft genau hinein. Schau auf den Weg daran vorbei.\n\n> **Übung:** Fahre auf einem leeren Parkplatz langsam Kreise und Achten. Dreh den Kopf bewusst schon zum nächsten Punkt, bevor du lenkst."},
{"slug": "bremsen", "category": "braking", "difficulty": 1, "sort": 3, "title": "Bremsen", "summary": "Die Vorderradbremse bringt den grössten Teil der Bremswirkung. Am kürzesten wird der Bremsweg, wenn du beide Bremsen richtig einsetzt.", "body": "Die Vorderradbremse bringt den grössten Teil der Bremswirkung. Am kürzesten wird der Bremsweg, wenn du beide Bremsen richtig einsetzt.\n\n1. Immer vorne und hinten zusammen bremsen.\n2. Die Vorderradbremse zuerst sanft anlegen und dann kräftig zuziehen, so baut sich der Druck sauber auf.\n3. Beim Bremsen aufrecht bleiben, nach vorne schauen und die Knie an den Tank drücken.\n4. Hat dein Motorrad ABS, darfst du im Notfall voll bremsen. Das ABS verhindert, dass die Räder blockieren.\n5. Beim langsamen Fahren die Vorderradbremse nur benutzen, wenn das Motorrad ganz gerade ist. Hast du eingelenkt, auf keinen Fall vorne bremsen, sonst kippt das Motorrad. Nimm dann die Hinterradbremse.\n\n> **Übung:** Übe Notbremsungen zuerst aus 30, dann aus 50 km/h auf einem abgesperrten Platz. Am besten in einem Fahrsicherheitstraining mit Instruktor."},
{"slug": "mit-sozius-fahren", "category": "traffic", "difficulty": 2, "sort": 4, "title": "Mit Sozius fahren", "summary": "Mit einer zweiten Person verändert sich das Fahrverhalten: Das Motorrad wird schwerer, träger und braucht länger zum Bremsen.", "body": "Mit einer zweiten Person verändert sich das Fahrverhalten: Das Motorrad wird schwerer, träger und braucht länger zum Bremsen.\n\n1. Die Beifahrerin oder der Beifahrer steigt erst auf, wenn du sicher stehst und die Bremse hältst.\n2. Beim Aufsteigen lehnst du das Motorrad leicht zur anderen Seite, also weg von der Seite, auf der die Person aufsteigt. So fängst du ihr Gewicht ab und das Motorrad kippt nicht um.\n3. Sozius hält sich an dir oder an den Haltegriffen fest und lehnt sich in Kurven mit dir mit, nicht dagegen.\n4. Mehr Abstand halten und früher bremsen.\n\n> **Gut zu wissen:** Vereinbart vor der Fahrt Zeichen, zum Beispiel zweimal auf die Schulter klopfen für eine Pause."},
{"slug": "assistenzfunktionen", "category": "basics", "difficulty": 2, "sort": 5, "title": "Assistenzfunktionen", "summary": "Viele Motorräder haben elektronische Helfer. Sie machen das Fahren sicherer, ersetzen aber keine saubere Fahrtechnik.", "body": "Viele Motorräder haben elektronische Helfer. Sie machen das Fahren sicherer, ersetzen aber keine saubere Fahrtechnik.\n\n1. ABS: verhindert, dass die Räder beim Bremsen blockieren.\n2. Traktionskontrolle: verhindert, dass das Hinterrad beim Beschleunigen durchdreht, besonders bei Nässe wichtig.\n3. Fahrmodi wie Regen, Strasse oder Sport ändern, wie stark und direkt der Motor reagiert. Bei Nässe den Regenmodus wählen.\n\n> **Wichtig:** Nicht jedes Motorrad hat jede dieser Assistenzfunktionen. Welche dein Motorrad hat und wie du sie bedienst, steht im Handbuch zu deinem Motorrad. Lies dort nach, bevor du losfährst."},
{"slug": "warnsymbole", "category": "basics", "difficulty": 1, "sort": 6, "title": "Warnsymbole", "summary": "Im Cockpit können Kontrollleuchten aufleuchten. An ihrer Farbe erkennst du, wie dringend es ist.", "body": "Im Cockpit können Kontrollleuchten aufleuchten. An ihrer Farbe erkennst du, wie dringend es ist.\n\n1. Rot: sofort anhalten, sobald es sicher möglich ist, und den Motor abstellen.\n2. Gelb oder Orange: bald prüfen oder in die Werkstatt fahren.\n3. Grün oder Blau: nur eine Information, kein Problem.\n4. Leuchtet während der Fahrt eine Warnleuchte, im Handbuch nachlesen oder in die Werkstatt fahren.\n\n> **Wichtig:** Die Symbole sehen nicht bei jedem Motorrad gleich aus, und nicht jedes Motorrad hat alle. Was die Leuchten an deinem Motorrad bedeuten, steht im Handbuch zu deinem Motorrad."},
{"slug": "anfahren", "category": "basics", "difficulty": 1, "sort": 7, "title": "Anfahren", "summary": "Sanftes Anfahren hängt vor allem an der Kupplung. Wer den Schleifpunkt kennt, würgt den Motor nicht mehr ab.", "body": "Sanftes Anfahren hängt vor allem an der Kupplung. Wer den Schleifpunkt kennt, würgt den Motor nicht mehr ab.\n\n1. Kupplung ziehen und den ersten Gang einlegen.\n2. Ein wenig Gas geben, damit die Drehzahl leicht steigt.\n3. Die Kupplung langsam kommen lassen, bis das Motorrad anrollt, und sie dort kurz halten. Das ist der Schleifpunkt.\n4. Sobald das Motorrad rollt, die Füsse auf die Rasten stellen und die Kupplung langsam ganz loslassen.\n5. Am Berg anfahren: Gas geben, und zwar nicht zu wenig. Dann die Kupplung langsam loslassen.\n\n> **Gut zu wissen:** Am Berg hältst du das Motorrad mit der Fussbremse, bis der Schleifpunkt erreicht ist, und lässt die Bremse erst dann los."},
{"slug": "wintervorbereitung", "category": "care", "difficulty": 2, "sort": 8, "title": "Wintervorbereitung", "summary": "Gut eingewintert startet dein Motorrad im Frühling ohne Ärger.", "body": "Gut eingewintert startet dein Motorrad im Frühling ohne Ärger.\n\n1. Motorrad gründlich waschen und gut trocknen lassen.\n2. Volltanken, damit der Tank innen nicht rostet.\n3. Kette reinigen und schmieren.\n4. Ein Erhaltungsladegerät an die Batterie anschliessen.\n5. Trocken und frostfrei abstellen, mit einer atmungsaktiven Abdeckung.\n6. Das Motorrad auf einen Ständer stellen, damit die Räder nicht auf dem Boden stehen. Geht das nicht, das Motorrad alle paar Wochen ein Stück verschieben.\n7. Alle paar Wochen den Motor starten und ein paar Minuten laufen lassen.\n\n> **Gut zu wissen:** In der Schweiz kannst du das Kontrollschild über den Winter beim Strassenverkehrsamt hinterlegen. So sparst du Verkehrssteuer und Versicherung."},
{"slug": "kettenpflege", "category": "care", "difficulty": 1, "sort": 9, "title": "Kettenpflege", "summary": "Eine gepflegte Kette hält länger und läuft leiser. Richtwert: alle 500 bis 1 000 km und nach jeder Regenfahrt.", "body": "Eine gepflegte Kette hält länger und läuft leiser. Richtwert: alle 500 bis 1 000 km und nach jeder Regenfahrt.\n\n1. Motor aus und den Leerlauf (N) einlegen, sonst lässt sich das Hinterrad nicht drehen.\n2. Motorrad auf den Montageständer stellen, damit sich das Hinterrad frei drehen lässt. Ohne Montageständer: Motorrad auf den Seitenständer stellen, eine Person zieht es zur Seite, sodass es nur noch auf Seitenständer und Vorderrad steht. Eine zweite Person kann dann das Hinterrad leicht drehen.\n3. Kette mit Kettenreiniger und einer Bürste sauber machen und trocknen lassen.\n4. Kettenspray auf die Innenseite der Kette sprühen und dabei das Rad langsam drehen.\n5. Einige Minuten einwirken lassen und überschüssiges Fett mit einem Lappen abwischen.\n6. Kettendurchhang prüfen. Den richtigen Wert findest du im Handbuch.\n\n> **Gut zu wissen:** Die Kette pflegst du am besten, wenn sie nach einer Fahrt noch leicht warm ist. Dann zieht das Fett besser ein."},
{"slug": "fahren-bei-naesse", "category": "weather", "difficulty": 2, "sort": 10, "title": "Fahren bei Nässe", "summary": "Bei Regen haben die Reifen weniger Grip. Mit ruhiger Fahrweise kommst du trotzdem sicher an.", "body": "Bei Regen haben die Reifen weniger Grip. Mit ruhiger Fahrweise kommst du trotzdem sicher an.\n\n1. Langsamer fahren und den Abstand verdoppeln.\n2. Bremsen, Gas geben und Lenken sanft und ohne Ruck.\n3. Weniger Schräglage in Kurven.\n4. Schachtdeckeln, Laub, Fahrbahnmarkierungen, Schienen und Dreck möglichst ausweichen. Das gilt auch bei trockener Strasse. Geht es nicht anders, aufrecht und ohne zu bremsen darüberfahren.\n\n> **Gut zu wissen:** Der erste Regen nach einer Trockenphase ist besonders rutschig, weil sich Staub und Öl auf der Strasse lösen. Auch Nebel macht die Strasse rutschig, oft fast noch mehr als eine ganz nasse Strasse: Die feine Feuchtigkeit bildet mit dem Schmutz einen schmierigen Film."},
{"slug": "schutzausruestung", "category": "gear", "difficulty": 1, "sort": 11, "title": "Schutzausrüstung", "summary": "Gute Ausrüstung schützt dich bei einem Sturz und auch vor Kälte und Nässe.", "body": "Gute Ausrüstung schützt dich bei einem Sturz und auch vor Kälte und Nässe.\n\n1. Helm mit gültiger Prüfnorm (ECE 22.06), der gut sitzt und nicht wackelt.\n2. Handschuhe, die die Knöchel und die Handflächen schützen.\n3. Jacke und Hose mit Protektoren an Schultern, Ellbogen, Hüfte und Knien.\n4. Ein Rückenprotektor ist sehr wichtig: Er schützt bei einem Sturz die Wirbelsäule.\n5. Ein Nierengurt stützt den Rücken und hält Bauch und Nieren warm.\n6. Feste Motorradstiefel, die den Knöchel schützen.\n\n> **Gut zu wissen:** Nach einem Sturz gehört der Helm ausgetauscht, auch wenn man keinen Schaden sieht. Helle Farben und Reflektoren helfen, dass andere dich früher sehen."},
{"slug": "fahren-in-der-gruppe", "category": "traffic", "difficulty": 2, "sort": 12, "title": "Fahren in der Gruppe", "summary": "In der Gruppe macht Motorradfahren Spass, wenn alle wissen, wie es läuft.", "body": "In der Gruppe macht Motorradfahren Spass, wenn alle wissen, wie es läuft.\n\n1. Vor der Fahrt Route, Pausen und Handzeichen absprechen.\n2. Auf geraden Strecken versetzt fahren, in Kurven hintereinander mit genug Abstand.\n3. Erfahrene Fahrer vorne und hinten, Anfängerinnen und Anfänger direkt hinter der Spitze.\n4. Jede und jeder fährt das eigene Tempo. Lass dich nicht zu schnellerem Fahren drängen.\n5. Mit einem Kommunikationssystem für den Helm, zum Beispiel von Sena oder Cardo, kannst du während der Fahrt mit der Gruppe sprechen oder Musik hören. Lass dich davon nicht ablenken und nutze es nur, wenn du dich sicher genug fühlst.\n\n> **Übung:** Starte mit einer kleinen Gruppe von drei bis vier Motorrädern auf einer bekannten Strecke."},
{"slug": "langsamfahren-und-wenden", "category": "basics", "difficulty": 2, "sort": 13, "title": "Langsamfahren & Wenden", "summary": "Langsam fahren ist schwieriger als schnell. Mit Kupplung, Hinterradbremse und Blick wird es aber ruhig und kontrolliert.", "body": "Langsam fahren ist schwieriger als schnell. Mit Kupplung, Hinterradbremse und Blick wird es aber ruhig und kontrolliert.\n\n1. Mit der Kupplung am Schleifpunkt fahren und ein wenig Gas halten.\n2. Die Hinterradbremse leicht schleifen lassen, das stabilisiert. Die Vorderradbremse beim Wenden nicht benutzen.\n3. Den Kopf weit drehen und zum Ziel der Wende schauen.\n4. Lenker einschlagen, Oberkörper aufrecht lassen, das Motorrad darf sich unter dir neigen.\n\n> **Übung:** Wende auf einem leeren Parkplatz innerhalb von zwei Parkfeldern und fahre langsam enger werdende Kreise."},
{"slug": "kurse", "category": "basics", "difficulty": 1, "sort": 14, "title": "Kurse", "summary": "Auf dem Weg zum Motorradausweis sind einige Kurse Pflicht. Danach helfen freiwillige Kurse, sicherer zu fahren.", "body": "Auf dem Weg zum Motorradausweis sind einige Kurse Pflicht. Danach helfen freiwillige Kurse, sicherer zu fahren.\n\n1. VKU (Verkehrskunde-Unterricht): Theorie dazu, wie man Gefahren im Verkehr erkennt und sich richtig verhält. Den VKU musst du nur machen, wenn du ihn nicht schon für das Auto gemacht hast. Er muss vor der praktischen Prüfung abgeschlossen sein.\n2. Grundkurs (Pflicht): 12 Stunden bei einer Fahrschule. Bei den Kategorien A1 und A musst du ihn innerhalb von 4 Monaten nach dem Lernfahrausweis machen. Ohne Grundkurs kannst du dich nicht zur Prüfung anmelden.\n3. WAB-Kurs (Weiterausbildung): ein Kurstag innerhalb von 12 Monaten nach der praktischen Prüfung. Mit dem Motorrad musst du ihn nur machen, wenn du ihn nicht mit dem Auto machen kannst.\n4. Kurventraining (freiwillig): verbessert Blickführung, Linienwahl und Schräglage in Kurven.\n\n> **Gut zu wissen:** Kurse bieten zum Beispiel der TCS und Fahrschulen an. Was genau für dich gilt, zum Beispiel ob ein Kurs vom Auto zählt, erfährst du beim Strassenverkehrsamt deines Kantons."}
]$json$::jsonb) as x(
  slug text, category text, difficulty smallint, sort smallint, title text, summary text, body text);

insert into public.tips (category_code, slug, difficulty, sort_order, published_at)
select category, slug, difficulty, sort, now() from _tips;

insert into public.tip_translations (tip_id, locale_code, title, summary, body_md)
select t.id, 'de', x.title, x.summary, x.body
from _tips x join public.tips t on t.slug = x.slug;

drop table _tips;
